import json, glob, os, numpy as np
from scipy.stats import spearmanr

def load_sig(fid):
    d = json.load(open(f'factors/{fid}.json'))
    art = d.get('signal_artifact')
    if art and os.path.exists('factors/'+art):
        return np.load('factors/'+art)
    # embedded artifact?
    va = d.get('validation',{}).get('signal_artifact')
    if va and isinstance(va, dict) and 'data' in va:
        import base64, zlib, io
        raw = base64.b64decode(va['data'])
        raw = zlib.decompress(raw)
        txt = raw.decode()
        # csv: skip header, parse floats (last col might be date)
        rows = []
        for line in txt.strip().splitlines()[1:]:
            parts = line.split(',')
            try:
                rows.append([float(x) for x in parts[1:]])
            except Exception:
                continue
        return np.array(rows)
    return None

fids = ['down_beta_60','cn10y_beta_60','spx_beta_60','vol_adj_mom_20_60','dxy_beta_cond_60x20','hs300_beta_60','intraday_ret_skew_20','vol_of_vol20x60','dd_duration_120_resid','vix_beta_cond_60x20','eurusd_beta_cond_60x20','sign_persist_20','streak_60','mom_accel_60_120','copper_gold_beta_20','hilo_pos_60']

sigs = {}
for fid in fids:
    a = load_sig(fid)
    if a is None:
        print(fid, '-> NO SIGNAL')
    else:
        sigs[fid] = a
        print(fid, '->', a.shape)

# align tails to shortest
names = list(sigs.keys())
n = min(sigs[k].shape[0] for k in names)
print('\naligned rows:', n)

corr = {}
for i in range(len(names)):
    for j in range(i+1, len(names)):
        a, b = names[i], names[j]
        x = sigs[a][-n:].reshape(-1)
        y = sigs[b][-n:].reshape(-1)
        m = ~(np.isnan(x) | np.isnan(y))
        if m.sum() < 1000:
            rho = float('nan')
        else:
            rho = spearmanr(x[m], y[m]).statistic
        corr[(a,b)] = rho
        if abs(rho) > 0.5:
            print(f"{a:24s} vs {b:24s} rho={rho:+.3f}")
