import json,glob,numpy as np,os
cands=['down_beta_60','cn10y_beta_60','spx_beta_60','vol_adj_mom_20_60','dxy_beta_cond_60x20','hs300_beta_60','hilo_vol_ratio_20','intraday_ret_skew_20','comm_basket_beta_60','vol_of_vol20x60','vol_regime_switch_20x60','vix_beta_cond_60x20','dd_duration_120_resid','eurusd_beta_cond_60x20','sign_persist_20','streak_60','mom_accel_60_120','range_skew_20','copper_gold_beta_20','hilo_pos_60']
sig={}
for f in glob.glob('factors/*.json'):
    if 'bak' in f or 'ensemble' in f: continue
    d=json.load(open(f))
    fid=d['factor_id']
    if fid not in cands: continue
    art=d.get('signal_artifact')
    if art:
        p=os.path.join('factors',art)
        if os.path.exists(p):
            try:
                a=np.load(p,allow_pickle=True)
                if a.ndim==2 and a.shape[1]==15:
                    sig[fid]=a
            except Exception: pass
print('loaded:',len(sig))
# correlation of factor signals: use last 250 rows, compute mean abs cross-sectional corr of ranks
keys=list(sig.keys())
# For each date, compute cross-sectional spearman corr between factor pairs; average over recent dates
import scipy.stats as st
last=250
pairs={}
for i in range(len(keys)):
    for j in range(i+1,len(keys)):
        a=sig[keys[i]][-last:]; b=sig[keys[j]][-last:]
        cs=[]
        for t in range(last):
            av=a[t]; bv=b[t]
            m=np.isfinite(av)&np.isfinite(bv)
            if m.sum()>=6:
                r=st.spearmanr(av[m],bv[m]).statistic
                cs.append(r)
        if cs: pairs[(keys[i],keys[j])]=np.mean(cs)
# print top correlated pairs
top=sorted(pairs.items(),key=lambda x:-abs(x[1]))[:20]
print('top |corr| pairs (recent 250d):')
for (k1,k2),v in top:
    print(f'  {k1:<24} vs {k2:<24} r={v:+.2f}')
